@import "@fontsource-variable/arimo";
@import "@fontsource-variable/newsreader/opsz.css";

/* Light (faithful): white paper, black ink, one grey (rgb 146) for secondary lines, pale grey
   media placeholders and hairline rules. No accent colour anywhere. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(0.979 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.979 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.94 0 0);
  --muted-foreground: oklch(0.666 0 0);
  --accent: oklch(0.965 0 0);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.86 0 0);
  --input: oklch(0.86 0 0);
  --ring: oklch(0 0 0);
  --highlight: oklch(0.666 0 0);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.88 0 0);
  --chart-1: oklch(0 0 0);
  --chart-2: oklch(0.35 0 0);
  --chart-3: oklch(0.55 0 0);
  --chart-4: oklch(0.72 0 0);
  --chart-5: oklch(0.86 0 0);
  --sidebar: oklch(0.979 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.965 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.86 0 0);
  --sidebar-ring: oklch(0 0 0);

  --typeface-body: "Arimo Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-display: "Newsreader Variable", ui-serif, Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 120rem;
  --page-gutter: 1rem;
  --section-y: 1.5rem;
}

/* The original is fluid: from 1024px the gutter and the section rhythm follow the window width
   (23px and ~65px at 1440). */
@media (min-width: 64rem) {
  :root {
    --page-gutter: 1.6vw;
    --section-y: 4.5vw;
  }
}

/* Dark (sibling, and the original's own black second half): black paper, white ink, the same
   grey, a deep grey for placeholders. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.16 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.16 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(1 0 0);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.2 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.22 0 0);
  --muted-foreground: oklch(0.666 0 0);
  --accent: oklch(0.22 0 0);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 18%);
  --input: oklch(1 0 0 / 22%);
  --ring: oklch(1 0 0);
  --highlight: oklch(0.666 0 0);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.3 0 0);
  --chart-1: oklch(1 0 0);
  --chart-2: oklch(0.8 0 0);
  --chart-3: oklch(0.62 0 0);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.3 0 0);
  --sidebar: oklch(0.12 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.22 0 0);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 18%);
  --sidebar-ring: oklch(1 0 0);
}
